// 只借冻结政治源，不创建授权/呈递；真实World必须消费S6适配器。
struct Missions: DiplomaticMissionRead,DiplomacyPresentationRead,DiplomaticEnvoyReportRead {
    DiplomaticMissionApproval approval;DiplomaticPresentationSource presentation;int* calls=nullptr;
    Outcome<DiplomaticMissionApproval> diplomatic_mission_for_acceptance(const StableId&,const StableId&)const override{return {false,{},common_failure("UnexpectedAcceptanceRead").error};}
    Outcome<DiplomaticMissionApproval> diplomatic_mission_source(const StableId& id)const override{return id==approval.mission_authority_fact_id?Outcome<DiplomaticMissionApproval>{true,approval,{}}:Outcome<DiplomaticMissionApproval>{false,{},common_failure("UnknownMission").error};}
    Outcome<DiplomaticMissionContinuity> diplomatic_mission_continuity(const StableId&,const StableId&)const override{if(calls)++*calls;return {true,{DiplomaticMissionContinuityKind::continue_work,{},{}},{}};}
    Outcome<DiplomaticPresentationSource> diplomatic_presentation_source(const StableId& id)const override{return id==presentation.fact_id?Outcome<DiplomaticPresentationSource>{true,presentation,{}}:Outcome<DiplomaticPresentationSource>{false,{},common_failure("UnknownPresentation").error};}
    Outcome<DiplomaticEnvoyReportSource> diplomatic_envoy_report_source(const StableId&)const override{return {false,{},common_failure("UnexpectedReportHistoryRead").error};}
};
// 只准具名Office的眼前本人，模拟原authorize严格等式，禁止同org另一岗位冒名。
struct Offices: OrganizationRead {
    StableId holder="representative";bool permitted=true;
    bool organization_exists(const StableId&)const override{return true;}
    bool organization_active(const StableId&)const override{return true;}
    bool institutional_obligation_allowed(const StableId&,const StableId&,const StableId&,const StableId&,Integer,Integer)const override{return false;}
    bool actor_accepts_duty(const StableId&,const StableId&)const override{return false;}
    std::optional<Integer> authority_epoch(const StableId& id)const override{return id=="south.office"||id=="north.office"?std::optional<Integer>{3}:std::nullopt;}
    Outcome<AuthorityProof> authorize(const ActingAuthority& a,const StableId& command,const ScopeRef& scope,Integer)const override{if(!permitted||a.actor_id!=holder||a.authority_epoch!=3||(a.office_id!="north.office"&&a.office_id!="south.office")||(command!="diplomatic_receive_envoy_report"&&command!="diplomatic_receive_passage"))return {false,{},common_failure("NotOfficeHolder").error};return {true,{a.organization_id,a.office_id,a.actor_id,command,scope,4,3,0,{}},{}};}
    std::optional<OrganizationMemberView> member_view(const StableId&,const StableId&)const override{return {};}
};
